code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Solid, non-background rows and columns are panel dividers.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_panels = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_panels = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # Use the panel with the most non-background cells as the source pattern.
    best = None
    best_count = 0
    for ri, (r0, r1) in enumerate(row_panels):
        for ci, (c0, c1) in enumerate(col_panels):
            count = sum(grid[r][c] != background for r in range(r0, r1) for c in range(c0, c1))
            if count > best_count:
                best_count, best = (ri, ci), (r0, r1, c0, c1)
    if best is None:
        return [row[:] for row in grid]

    r0, r1, c0, c1 = best
    pattern = [row[c0:c1] for row in grid[r0:r1]]
    out = [row[:] for row in grid]
    for pr0, pr1 in row_panels:
        for pc0, pc1 in col_panels:
            if pr1 - pr0 != len(pattern) or pc1 - pc0 != len(pattern[0]):
                continue
            for dr in range(len(pattern)):
                for dc in range(len(pattern[0])):
                    out[pr0 + dr][pc0 + dc] = pattern[dr][dc]
    return out
'''
